mapper.select:
SELECT s.snapshot_id AS snapshotId, s.reservation_code AS reservationCode, s.trip_type AS tripType, s.is_direct_only AS directOnly, DATE_FORMAT(s.dep_date, '%Y-%m-%d') AS depDate, s.dep_airport AS depAirport, s.dep_airline_code AS depAirlineCode, s.dep_flight_no AS depFlightNo, DATE_FORMAT(s.return_date, '%Y-%m-%d') AS returnDate, s.return_airport AS returnAirport, s.return_airline_code AS returnAirlineCode, s.return_flight_no AS returnFlightNo, s.promo_card_code AS promoCardCode, s.seat_class AS seatClass, s.passenger_type AS passengerType, s.base_fare AS baseFare, s.tax AS tax, s.q_charge AS qCharge, s.current_rank AS currentRank, DATE_FORMAT(s.captured_at, '%Y-%m-%d %H:%i:%s') AS capturedAt, s.fare1, s.fare1_agency_code AS fare1AgencyCode, s.fare1_agency_name AS fare1AgencyName, s.fare2, s.fare2_agency_code AS fare2AgencyCode, s.fare2_agency_name AS fare2AgencyName, s.fare3, s.fare3_agency_code AS fare3AgencyCode, s.fare3_agency_name AS fare3AgencyName, s.fare4, s.fare4_agency_code AS fare4AgencyCode, s.fare4_agency_name AS fare4AgencyName, s.fare5, s.fare5_agency_code AS fare5AgencyCode, s.fare5_agency_name AS fare5AgencyName, s.fare6, s.fare6_agency_code AS fare6AgencyCode, s.fare6_agency_name AS fare6AgencyName, s.fare7, s.fare7_agency_code AS fare7AgencyCode, s.fare7_agency_name AS fare7AgencyName, s.fare8, s.fare8_agency_code AS fare8AgencyCode, s.fare8_agency_name AS fare8AgencyName, s.fare9, s.fare9_agency_code AS fare9AgencyCode, s.fare9_agency_name AS fare9AgencyName, s.fare10, s.fare10_agency_code AS fare10AgencyCode, s.fare10_agency_name AS fare10AgencyName, s.fare11, s.fare11_agency_code AS fare11AgencyCode, s.fare11_agency_name AS fare11AgencyName, s.fare12, s.fare12_agency_code AS fare12AgencyCode, s.fare12_agency_name AS fare12AgencyName, s.fare13, s.fare13_agency_code AS fare13AgencyCode, s.fare13_agency_name AS fare13AgencyName, s.fare14, s.fare14_agency_code AS fare14AgencyCode, s.fare14_agency_name AS fare14AgencyName, s.fare15, s.fare15_agency_code AS fare15AgencyCode, s.fare15_agency_name AS fare15AgencyName, s.fare16, s.fare16_agency_code AS fare16AgencyCode, s.fare16_agency_name AS fare16AgencyName, s.fare17, s.fare17_agency_code AS fare17AgencyCode, s.fare17_agency_name AS fare17AgencyName, s.fare18, s.fare18_agency_code AS fare18AgencyCode, s.fare18_agency_name AS fare18AgencyName, s.fare19, s.fare19_agency_code AS fare19AgencyCode, s.fare19_agency_name AS fare19AgencyName, s.fare20, s.fare20_agency_code AS fare20AgencyCode, s.fare20_agency_name AS fare20AgencyName FROM FLIGHT_PRICE_SNAPSHOT s WHERE s.reservation_code = #{reservationCode}
AND s.captured_at >= #{fromDt}
AND s.captured_at < #{toDt}
ORDER BY s.captured_at DESC, s.snapshot_id DESC LIMIT #{limit}
